<div class="cms-inspector-section">
    <h4>Datos y reutilización</h4>
    <div class="cms-inspector-actions"><button type="button" class="cms-inspector-action" @click="copySelected('json')">Datos JSON</button><button type="button" class="cms-inspector-action" @click="copySelected('blade')">Copiar Blade</button><span role="status" class="admin-field-hint" x-text="copyStatus"></span></div>
    <textarea x-show="dataExport" :value="dataExport" readonly rows="6" aria-label="Código del bloque seleccionado" class="admin-control w-full font-mono text-xs" @focus="$event.target.select()"></textarea>
    <label class="admin-field-label">Clases permitidas del proyecto<input type="text" class="admin-control w-full" :value="appearanceClasses()" @change="setAppearanceClasses($event.target.value)" placeholder="Heredar"><span class="admin-field-hint" x-text="'Disponibles: ' + (Array.isArray(editorOptions.appearanceClasses) ? editorOptions.appearanceClasses : Object.keys(editorOptions.appearanceClasses || {})).join(', ')"></span></label>
</div>
<details class="cms-inspector-section"><summary>Valores de presentación guardados</summary><p class="admin-field-hint">Consulta los valores propios, incluidos los ajustes personalizados conservados. Este visor no los modifica.</p><textarea readonly rows="8" class="admin-control w-full font-mono text-xs" :value="savedPresentation()" aria-label="Valores de presentación guardados"></textarea></details>
<details x-show="bindingFields().length" class="cms-inspector-section"><summary>Datos públicos dinámicos</summary><template x-for="field in bindingFields()" :key="field.key"><fieldset class="cms-inspector-section"><legend class="admin-field-label" x-text="field.label"></legend><select class="admin-control w-full" :value="bindingFor(field.key).source || ''" @change="setBindingSource(field.key, $event.target.value)" :aria-label="'Fuente de ' + field.label"><template x-for="(label, source) in bindingSourceOptions()" :key="source"><option :value="source" x-text="label"></option></template></select><template x-if="bindingFor(field.key).source"><div><select class="admin-control w-full" :value="bindingFor(field.key).field || ''" @change="setBindingValue(field.key, 'field', $event.target.value)" :aria-label="'Campo público para ' + field.label"><option value="">Selecciona un campo</option><template x-for="(descriptor, name) in bindingSourceFields(field.key)" :key="name"><option :value="name" x-text="descriptor.label || name"></option></template></select><input x-show="bindingFor(field.key).source !== 'item'" type="number" min="1" step="1" class="admin-control w-full" :value="bindingFor(field.key).id || ''" @change="setBindingValue(field.key, 'id', $event.target.value)" aria-label="ID público de la referencia" placeholder="ID de la referencia pública"></div></template></fieldset></template></details>
